68	+/* ===== Người treo dù: IK hai khớp giải tích (src/explore/pilot/ik.ts) =====
69	+   Thuần số học, không import three, không cấp phát: vectơ là mảng số (ArrayLike / number[]) dùng lại.
70	+   Dùng cho cánh tay (vai → khuỷu → cổ tay) tới quai phanh; đích ngoài tầm được kẹp về tầm với để khớp không gãy. */
71	+
72	+/* Hai khớp: gốc a, dài l1 (a → khuỷu), l2 (khuỷu → đầu mút), đích t, cực p là ĐIỂM trong cùng hệ tọa độ (khuỷu nằm lệch về phía p so với đường a → đích).
73	+   Ghi vị trí khuỷu vào outElbow, đầu mút (đã kẹp vào tầm với) vào outEnd; trả true nếu đích nằm trong tầm [|l1 − l2|, (l1 + l2) × 0.999] */
74	+export function plTwoBone(a: ArrayLike<number>, l1: number, l2: number, t: ArrayLike<number>, p: ArrayLike<number>, outElbow: number[], outEnd: number[]): boolean {
75	+  const ax = a[0], ay = a[1], az = a[2];
76	+  let dx = t[0] - ax, dy = t[1] - ay, dz = t[2] - az;
77	+  let dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
78	+  const maxR = (l1 + l2) * 0.999, minR = Math.abs(l1 - l2) * 1.001 + 1e-6;
79	+  const inReach = dist >= minR && dist <= maxR;
80	+  let ux: number, uy: number, uz: number;
81	+  if (dist > 1e-9) { ux = dx / dist; uy = dy / dist; uz = dz / dist; }
82	+  else { ux = 1; uy = 0; uz = 0; dist = 0; }   // đích trùng gốc: chọn hướng tùy ý, vẫn không NaN
83	+  const c = dist > maxR ? maxR : dist < minR ? minR : dist;
84	+  /* Khuỷu: x dọc trục a → đích, h vuông góc theo hướng cực */
85	+  const x = (l1 * l1 - l2 * l2 + c * c) / (2 * c);
86	+  const h = Math.sqrt(Math.max(0, l1 * l1 - x * x));
87	+  let px = p[0] - ax, py = p[1] - ay, pz = p[2] - az;
88	+  const along = px * ux + py * uy + pz * uz;
89	+  px -= along * ux; py -= along * uy; pz -= along * uz;   // phần cực vuông góc với trục
90	+  let pl = Math.sqrt(px * px + py * py + pz * pz);
91	+  if (pl < 1e-6) {   // cực song song trục: lấy trục tọa độ ít song song nhất
92	+    const bx = Math.abs(ux) < 0.9 ? 1 : 0, by = bx ? 0 : 1;
93	+    px = by * uz - 0 * uy; py = 0 * ux - bx * uz; pz = bx * uy - by * ux;   // b × u với b = (bx, by, 0)
94	+    pl = Math.sqrt(px * px + py * py + pz * pz) || 1;
95	+  }
96	+  px /= pl; py /= pl; pz /= pl;
97	+  outElbow[0] = ax + ux * x + px * h; outElbow[1] = ay + uy * x + py * h; outElbow[2] = az + uz * x + pz * h;
98	+  outEnd[0] = ax + ux * c; outEnd[1] = ay + uy * c; outEnd[2] = az + uz * c;
99	+  return inReach;
100	+}
101	diff --git a/src/explore/pilot/react.ts b/src/explore/pilot/react.ts
102	new file mode 100644
103	index 0000000..7966f19
104	--- /dev/null
105	+++ b/src/explore/pilot/react.ts
106	@@ -0,0 +1,176 @@
107	+/* ===== Người treo dù: phản ứng tư thế theo chuyển động (src/explore/pilot/react.ts) =====
108	+   Thuần số học, không import three, không chạm DOM, không cấp phát trong step(). Biến trạng thái bay (rẽ, tăng/giảm tốc, lên/xuống, gió)
109	+   thành các góc tư thế; bước sau (bones.ts) mới áp góc lên xương. Thiết kế: docs/superpowers/specs/2026-11-12-nguoi-du-luon-that-design.md §5.
110	+
111	+   Hệ cục bộ của dù: +X hướng bay, +Y lên, +Z phải; yaw tăng = quay trái; `bank > 0` = nghiêng trái. Người treo dưới điểm móc.
112	+   Dấu của từng trường PlPose (dương nghĩa là gì, nhìn từ người bay, quay mặt về hướng bay):
113	+     swingRoll  > 0  quay cả người quanh +X (quy tắc bàn tay phải): thân dưới điểm móc văng sang TRÁI (−Z)       ; rẽ trái → âm (văng ra ngoài)
114	+     swingPitch > 0  quay cả người quanh +Z: thân văng RA TRƯỚC (+X)                                              ; tăng tốc → âm (tụt ra sau), hãm → dương
115	+     swingYaw   > 0  quay cả người quanh +Y: xoay sang TRÁI                                                       ; chỉ do gió
116	+     spineRoll  > 0  thân trên nghiêng sang TRÁI (−Z)                                                             ; rẽ trái → dương (nghiêng vào lượt rẽ)
117	+     spinePitch > 0  thân trên chúi RA TRƯỚC                                                                      ; tăng tốc → dương, lên cao → âm (ngả)
118	+     spineTwist > 0  vai xoay sang TRÁI                                                                           ; rẽ trái → dương
119	+     headYaw    > 0  đầu quay sang TRÁI                                                                           ; rẽ trái → dương
120	+     headRoll   > 0  đầu nghiêng sang TRÁI so với thân (bù một phần góc nghiêng của thân + lắc, giữ đầu gần thẳng)
121	+     legSide    > 0  hai chân đưa sang TRÁI                                                                       ; rẽ trái → âm (quán tính)
122	+     legFore    > 0  hai chân đưa RA TRƯỚC                                                                        ; tăng tốc → âm, hãm → dương
123	+     kneeL/kneeR     độ gập thêm của gối, ≥ 0 (không gập ngược), cộng lên `base.knee`; hãm thì gập
124	+     legSplit   > 0  hai chân dạng ra thêm
125	+     brakeL/brakeR   0..1 mức kéo quai phanh (0 = thả, 1 = kéo hết `toggle.travel`)
126	+     packRoll   > 0  ba lô nghiêng sang TRÁI; packPitch > 0 ba lô chúi ra trước; strap: góc phất đuôi đai (rad, hai chiều)
127	+   Tất cả là góc CỘNG THÊM lên tư thế nền (0 = tư thế nền). */
128	+import { CONFIG } from '../../config';
129	+
130	+export interface PlSignals { turn: number; acc: number; vy: number; wind: number }   // turn, acc, vy đã kẹp [-1, 1] (turn > 0 = rẽ trái); wind 0..1 mức gió thời tiết
131	+export interface PlPose {
132	+  swingRoll: number; swingPitch: number; swingYaw: number;   // rad, cả người quanh điểm treo
133	+  spineRoll: number; spinePitch: number; spineTwist: number; // rad, tổng cho 3 đốt
134	+  headYaw: number; headRoll: number;                         // rad
135	+  legSide: number; legFore: number; kneeL: number; kneeR: number; legSplit: number;   // rad
136	+  brakeL: number; brakeR: number;                            // 0..1
137	+  packRoll: number; packPitch: number; strap: number;        // rad, chuyển động phụ
138	+}
139	+
140	+/* Chỉ số kênh lò xo (thứ tự trùng PlPose) */
141	+const C_SWR = 0, C_SWP = 1, C_SWY = 2, C_SPR = 3, C_SPP = 4, C_SPT = 5, C_HDY = 6, C_HDR = 7, C_LGS = 8, C_LGF = 9, C_KNL = 10, C_KNR = 11, C_LSP = 12, C_BRL = 13, C_BRR = 14, C_PKR = 15, C_PKP = 16, C_STR = 17, NCH = 18;
142	+
143	+const TAU = Math.PI * 2;
144	+const fin = (v: number): number => (Number.isFinite(v) ? v : 0);
145	+const clamp = (v: number, lo: number, hi: number): number => (v < lo ? lo : v > hi ? hi : v);
146	+const clampSym = (v: number): number => clamp(fin(v), -1, 1);
147	+
148	+/* Bộ sinh số ngẫu nhiên riêng theo seed (mulberry32): không đụng chuỗi rand() có seed dùng chung của cảnh */
149	+function plRng(seed: number): () => number {
150	+  let s = (Math.floor(fin(seed)) ^ 0x9e3779b9) >>> 0;
151	+  return () => { s = (s + 0x6d2b79f5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
152	+}
153	+
154	+export class PlReact {
155	+  readonly pose: PlPose = { swingRoll: 0, swingPitch: 0, swingYaw: 0, spineRoll: 0, spinePitch: 0, spineTwist: 0, headYaw: 0, headRoll: 0, legSide: 0, legFore: 0, kneeL: 0, kneeR: 0, legSplit: 0, brakeL: 0, brakeR: 0, packRoll: 0, packPitch: 0, strap: 0 };
156	+  private x = new Float64Array(NCH);        // giá trị kênh
157	+  private v = new Float64Array(NCH);        // vận tốc kênh
158	+  private w = new Float64Array(NCH);        // tần số góc rad/s của lò xo từng kênh
159	+  private z = new Float64Array(NCH);        // hệ số tắt từng kênh
160	+  private tg = new Float64Array(NCH);       // đích tạm của bước hiện tại
161	+  private ph = new Float64Array(8);         // pha nhiễu gió theo seed
162	+  private gustAmp: number;
163	+  private t = 0;                            // s thời gian nhiễu gió
164	+
165	+  /* opts.gust: ghi đè CONFIG.explore.pilot.gust.amp (rad), 0 = không nhiễu (dùng trong test) */
166	+  constructor(seed: number, opts?: { gust?: number }) {
167	+    const P = CONFIG.explore.pilot, S = P.spring, rnd = plRng(seed);
168	+    this.gustAmp = opts && opts.gust !== undefined ? opts.gust : P.gust.amp;
169	+    for (let i = 0; i < this.ph.length; i++) this.ph[i] = rnd() * TAU;
170	+    const grp: number[][] = [];
171	+    grp[C_SWR] = grp[C_SWP] = grp[C_SWY] = S.swing;
172	+    grp[C_SPR] = grp[C_SPP] = grp[C_SPT] = S.spine;
173	+    grp[C_HDY] = grp[C_HDR] = S.head;
174	+    grp[C_LGS] = grp[C_LGF] = grp[C_KNL] = grp[C_KNR] = grp[C_LSP] = S.legs;
175	+    grp[C_BRL] = grp[C_BRR] = S.brake;
176	+    grp[C_PKR] = grp[C_PKP] = grp[C_STR] = S.pack;
177	+    for (let i = 0; i < NCH; i++) { this.w[i] = TAU * grp[i][0]; this.z[i] = grp[i][1]; }
178	+    this.reset();
179	+  }
180	+
181	+  /* Về tư thế nghỉ: mọi góc 0, hai phanh ở mức nền, nhiễu gió về pha đầu */
182	+  reset(): void {
183	+    this.x.fill(0); this.v.fill(0); this.t = 0;
184	+    this.x[C_BRL] = this.x[C_BRR] = CONFIG.explore.pilot.brake.base;
185	+    this.write();
186	+  }
187	+
188	+  /* Tiến một khung. dt không hợp lệ (≤ 0, NaN) thì bỏ qua; dt > dtMax bị kẹp. Chia bước ≤ min(dtMax/4, 1/60) cho lò xo bán ẩn ổn định */
189	+  step(sig: PlSignals, dt: number): void {
190	+    if (!(dt > 0)) return;
191	+    const P = CONFIG.explore.pilot;
192	+    if (dt > P.dtMax) dt = P.dtMax;
193	+    const turn = clampSym(sig.turn), acc = clampSym(sig.acc), vy = clampSym(sig.vy), wind = clamp(fin(sig.wind), 0, 1);
194	+    const hMax = Math.min(P.dtMax / 4, 1 / 60), n = Math.max(1, Math.ceil(dt / hMax - 1e-9)), h = dt / n;
195	+    for (let s = 0; s < n; s++) {
196	+      this.t += h;
197	+      this.targets(turn, acc, vy, wind);
198	+      const x = this.x, v = this.v, w = this.w, z = this.z, tg = this.tg;
199	+      for (let i = 0; i < NCH; i++) {
200	+        /* x'' = −ω²(x − đích) − 2ζω x'; vận tốc cập nhật trước, vị trí dùng vận tốc mới (bán ẩn) */
201	+        v[i] += (-w[i] * w[i] * (x[i] - tg[i]) - 2 * z[i] * w[i] * v[i]) * h;
202	+        x[i] += v[i] * h;
203	+      }
204	+    }
205	+    this.write();
206	+  }
207	+
208	+  /* Đích của từng kênh từ tín hiệu và nhiễu gió */
209	+  private targets(turn: number, acc: number, vy: number, wind: number): void {
210	+    const P = CONFIG.explore.pilot, A = P.amp, B = P.brake, G = P.gust, tg = this.tg, x = this.x, ph = this.ph, t = this.t;
211	+    const ga = this.gustAmp * (1 + G.windGain * wind);
212	+    /* ba kênh nhiễu mượt: mỗi kênh là trung bình hai sin tần số khác nhau, pha theo seed; g[k] ∈ [−1, 1] */
213	+    const f = G.freq;
214	+    const g0 = 0.5 * (Math.sin(TAU * f[0] * t + ph[0]) + Math.sin(TAU * f[1] * 1.7 * t + ph[1]));
215	+    const g1 = 0.5 * (Math.sin(TAU * f[1] * t + ph[2]) + Math.sin(TAU * f[2] * 1.3 * t + ph[3]));
216	+    const g2 = 0.5 * (Math.sin(TAU * f[2] * t + ph[4]) + Math.sin(TAU * f[0] * 2.3 * t + ph[5]));
217	+    const g3 = Math.sin(TAU * f[1] * 1.9 * t + ph[6]), g4 = Math.sin(TAU * f[2] * 1.4 * t + ph[7]);   // phụ: hai chân lệch pha
218	+    tg[C_SWR] = -turn * A.swingRoll + ga * g0;
219	+    tg[C_SWP] = -acc * A.swingPitch + ga * g1;
220	+    tg[C_SWY] = ga * g2 * 0.6;
221	+    tg[C_SPR] = turn * A.leanRoll;
222	+    tg[C_SPP] = acc * A.leanPitch - vy * A.leanPitch * 0.5;
223	+    tg[C_SPT] = turn * A.twist;
224	+    tg[C_HDY] = turn * A.headYaw;
225	+    /* đầu giữ thẳng: bù phần nghiêng thực của đầu (thân nghiêng trái dương, quay quanh điểm treo làm đầu nghiêng phải khi swingRoll > 0) */
