250	+}
251	+
252	+/* ------------------------- Tín hiệu từ hai trạng thái liên tiếp ------------------------- */
253	+/* Trạng thái lấy mẫu của một dù. Ba trường cuối tùy chọn (thiếu thì coi là 0 / false): bộ lọc acc, vy và cờ đã có tốc độ hợp lệ */
254	+export interface PlTrack { x: number; y: number; z: number; speed: number; has: boolean; acc?: number; vy?: number; hasSpeed?: boolean }
255	+
256	+const SMOOTH_S = 0.15;     // s hằng số thời gian lọc một cực cho acc / vy (ước lượng)
257	+const TELEPORT_MS = 300;   // m/s — nhanh hơn mức này coi là nhảy vị trí (vào phòng, sửa lỗi mạng), bỏ qua mẫu (ước lượng)
258	+
259	+/* Tính tín hiệu cho mọi dù (của mình lẫn người khác, đều từ vị trí + bank). Không cấp phát; prev được cập nhật tại chỗ.
260	+   turnInput (tùy chọn, dù của mình): −1/0/1 như GliderInput.turn (+1 = trái); trộn nửa đường để tay đi trước thân */
261	+export function plSignals(out: PlSignals, prev: PlTrack, x: number, y: number, z: number, bank: number, dt: number, wind: number, turnInput?: number): void {
262	+  const E = CONFIG.explore;
263	+  out.wind = clamp(fin(wind), 0, 1);
264	+  let turn = clampSym(bank / E.bankMax);
265	+  if (turnInput !== undefined && Number.isFinite(turnInput)) turn += (clampSym(turnInput) - turn) * 0.5;
266	+  out.turn = turn;
267	+  if (!Number.isFinite(x + y + z) || !(dt > 0) || !Number.isFinite(dt)) { out.acc = clampSym(prev.acc || 0); out.vy = clampSym(prev.vy || 0); return; }   // mẫu xấu: giữ giá trị lọc cũ
268	+  if (!prev.has) { prev.x = x; prev.y = y; prev.z = z; prev.speed = 0; prev.has = true; prev.hasSpeed = false; prev.acc = 0; prev.vy = 0; out.acc = 0; out.vy = 0; return; }
269	+  const dx = x - prev.x, dz = z - prev.z, sp = Math.sqrt(dx * dx + dz * dz) / dt, vyRaw = (y - prev.y) / dt;
270	+  let accRaw = 0, vyN = 0;
271	+  if (Math.abs(sp) > TELEPORT_MS || Math.abs(vyRaw) > TELEPORT_MS) { prev.hasSpeed = false; }   // nhảy vị trí: bỏ mẫu, bộ lọc giữ nguyên
272	+  else {
273	+    if (prev.hasSpeed) accRaw = clampSym((sp - prev.speed) / dt / E.speedAccel);
274	+    vyN = clampSym(vyRaw / E.climbRate);
275	+    prev.speed = sp; prev.hasSpeed = true;
276	+    const a = 1 - Math.exp(-dt / SMOOTH_S);
277	+    prev.acc = (prev.acc || 0) + (accRaw - (prev.acc || 0)) * a;
278	+    prev.vy = (prev.vy || 0) + (vyN - (prev.vy || 0)) * a;
279	+  }
280	+  prev.x = x; prev.y = y; prev.z = z;
281	+  out.acc = clampSym(prev.acc || 0); out.vy = clampSym(prev.vy || 0);
282	+}
